{"code": "export async function main(input: { project: string }) {
  const { issues } = await sdk.sentry.listIssues({ project: input.project });

  // Unresolved issues with at least 0 events (count >= 0 is always true, but kept explicit).
  const target = issues.filter(i => i.status === "unresolved" && i.count >= 0);

  // Several Sentry issues can share a culprit: one Linear issue per culprit at most.
  const culprits = Array.from(new Set(target.map(i => i.culprit)));

  const report: any[] = [];
  const created: any[] = [];

  for (const culprit of culprits) {
    const { issues: found } = await sdk.linear.searchIssues({ query: culprit });
    const needle = culprit.toLowerCase();
    const mentioned = found.filter(
      l => l.title.toLowerCase().includes(needle) || (l.description ?? "").toLowerCase().includes(needle)
    );
    if (mentioned.length > 0) {
      report.push({ culprit, action: "exists", linear: mentioned.map(m => m.identifier) });
      continue;
    }
    const placeholder = await sdk.linear.createIssue({
      title: `[Sentry] ${culprit}`,
      description: culprit,
    });
    created.push({ culprit, placeholder });
    report.push({ culprit, action: "create", title: `[Sentry] ${culprit}` });
  }

  return { sentryIssues: target.length, culprits, report, created };
}", "input": {"project": "api"}}

{"code": "export async function main(input: {}) {
  const queries = ["orders.ts", "reserveStock", "Sentry"];
  const out: any = {};
  for (const q of queries) {
    out[q] = (await sdk.linear.searchIssues({ query: q })).issues.map(i => ({ id: i.identifier, title: i.title, description: i.description }));
  }
  return out;
}", "input": {}}
